checks[10]=c['decisions'][0]['question']=='Which identity provider handles volunteer sign-in?' and c['decisions'][0]['upstream'][0]['item']=='FR-001' and len(re.findall(r'\\[NEEDS ADR:',prd))==1
checks[11]=not list(Path('docs/specs/adr').glob('ADR-*.md')) and sum(d['state']=='resolved' for d in c['decisions'])==1
checks[12]=[(e['source'],e['kind'],e['classification']) for e in c['evidence']]==[('PRD-001','prd','context'),('POL-001#SET-01','policy','policy'),('POL-001#SET-02','policy','policy')] and f['inspection_scope']==[]
checks[13]=[x for x in f['upstream'] if x['id']=='POL-001']==[dict(id='POL-001',item='SET-02',relation='informed_by',version=3,hash=None)] and s.count('{id: POL-001, item: SET-01, relation: constrains, version: 3, hash: null}')==1
headings=['## 1. Context and scope','## 2. Quality drivers','## 3. Components','## 4. Architectural questions','## 5. Evidence inspected','## 6. Deployment','## 7. Requirement changes proposed to the PRD owner','## 8. Open questions','## Change Log']
checks[14]=re.findall(r'"'^## .+$'"',s,re.M)==headings and not any(x in s for x in ('<"'!--'"','ARCH-000','PRD-000','YYYY-MM-DD')) and '"'```mermaid'"\\nflowchart' in s
resolution='Policy resolution: interview.max_calls=8 (default); architecture.mandated_platforms=Org A Identity Platform (OIDC) for identity and authentication (POL-001#SET-01); quality.required_categories=+compliance,+accessibility (POL-001#SET-02)'
checks[15]=f\"codex (session {f['generated_by']['session']})\" in s.splitlines()[-1] and s.splitlines()[-1].endswith(resolution+' | all |')
def style_walk(node,key=None):
